package dev.nodi.android
import android.content.Context
object NodiText {
 fun language(c:Context)=c.getSharedPreferences("nodi_ui",Context.MODE_PRIVATE).getString("language","en") ?: "en"
 fun text(c:Context,value:CharSequence?):String {
  val source=value?.toString() ?: "";val lang=language(c);if(lang=="uk")return source
  val index=if(lang=="ru")1 else 0
  words[source]?.let{return it[index]}
  for((key,pair) in words) if((key.endsWith(":")||key.endsWith(" "))&&source.startsWith(key)) return pair[index]+source.removePrefix(key)
  return source
 }
